194: nsresult ShadowRoot::Bind() {
195:   MOZ_ASSERT(!IsInComposedDoc(), "Forgot to unbind?");
196:   if (Host()->IsInComposedDoc()) {
197:     SetIsConnected(true);
198:     Document* doc = OwnerDoc();
199:     doc->AddComposedDocShadowRoot(*this);
200:     // If our stylesheets somehow mutated when we were disconnected, we need to
201:     // ensure that our style data gets flushed as appropriate.
202:     if (mServoStyles && Servo_AuthorStyles_IsDirty(mServoStyles.get())) {
203:       doc->RecordShadowStyleChange(*this);
204:     }
205:   }
206: 
207:   BindContext context(*this);
208:   for (nsIContent* child = GetFirstChild(); child;
209:        child = child->GetNextSibling()) {
210:     nsresult rv = child->BindToTree(context, *this);
211:     NS_ENSURE_SUCCESS(rv, rv);
212:   }
213: 
214:   return NS_OK;
215: }
