217: void ShadowRoot::Unbind() {
218:   UnbindContext context(*this, /* aBatchState = */ nullptr);
219:   if (IsInComposedDoc()) {
220:     SetIsConnected(false);
221:     OwnerDoc()->RemoveComposedDocShadowRoot(*this);
222:   }
223:   for (nsIContent* child = GetFirstChild(); child;
224:        child = child->GetNextSibling()) {
225:     child->UnbindFromTree(context);
226:   }
227: 
228:   MutationObservers::NotifyParentChainChanged(this);
229: }
